            last_verified_error_kind?: "rejected" | "unavailable";
            /**
             * Format: date-time
             * @description When keys were first saved for this mode.
             */
            created_at: string;
            /**
             * Format: date-time
             * @description When the connection last changed.
             */
            updated_at: string;
